pub fn stable_id(project_id: &str, path: &str, symbol: &str) -> NodeId {
    let mut key = Vec::with_capacity(project_id.len() + path.len() + symbol.len() + 2);
    key.extend_from_slice(project_id.as_bytes());
    key.push(0);
    key.extend_from_slice(path.as_bytes());
    key.push(0);
    key.extend_from_slice(symbol.as_bytes());
    NodeId::from_content(&key)
}

fn collect_calls(body: TsNode, source: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut stack = vec![body];
    while let Some(node) = stack.pop() {
        if node.kind() == "call_expression" {
            if let Some(name) = node
                .child_by_field_name("function")
                .and_then(|function| callee_name(function, source))
            {
                out.push(name);
            }
        }
        let mut cursor = node.walk();
        for child in node.children(&mut cursor) {
            stack.push(child);
        }
    }
    out.sort();
    out.dedup();
    out
}

const READ_FILE_MAX_CHARS: usize = 24_000;
fn read_file(ctx: &ToolContext, input: &Value) -> ToolOutcome {
    let Some(path) = input.get("path").and_then(|p| p.as_str()) else {
        return ToolOutcome::error("falta el argumento 'path'");
    };

    let (resolved, access) = resolve_and_classify(ctx, path);
    match access {
        Access::Allowed => {}
        Access::Secret => {
            return ToolOutcome::error(format!(
                "acceso denegado: '{path}' es una credencial o secreto"
            ))
        }
        Access::Outside => {
            return ToolOutcome::error(format!(
                "acceso denegado: '{path}' está fuera del proyecto"
            ))
        }
        Access::Noise => {
            return ToolOutcome::error(format!(
                "'{path}' es un artefacto generado; no se lee por defecto"
            ))
        }
    }

    let contenido = match std::fs::read_to_string(&resolved) {
        Ok(c) => c,
        Err(e) => return ToolOutcome::error(format!("no se pudo leer '{path}': {e}")),
    };

    if contenido.len() > READ_FILE_MAX_CHARS {
        let corte = contenido
            .char_indices()
            .take(READ_FILE_MAX_CHARS)
            .last()
            .map(|(i, c)| i + c.len_utf8())
            .unwrap_or(0);
        ToolOutcome::ok(format!(
            "{}\n\n[recortado: {} de {} caracteres]",
            &contenido[..corte],
            READ_FILE_MAX_CHARS,
            contenido.len()
        ))
    } else {
        ToolOutcome::ok(contenido)
    }
}

pub fn enabled_count(items: &[bool]) -> usize { items.iter().filter(|flag| **flag).count() }
pub fn byte_length(value: &str) -> usize { value.len() }
pub fn middle_sorted(items: &mut [i32]) -> Option<i32> { if items.is_empty() { return None; } items.sort(); Some(items[items.len()/2]) }
pub fn next_index(i: usize, len: usize) -> Option<usize> { if len == 0 { None } else { Some((i+1)%len) } }
pub fn bounded(value: i32, limit: i32) -> Result<i32, &'static str> { if limit < 0 { return Err("negative limit"); } Ok(value.clamp(0,limit)) }

